    sciense_resourcedecision: function(){
        var selection = this.getSelectionModel().getSelected();

        if (selection){
            var rest = this.factoryRestful();
            var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

            mask.show();
            rest.doRequest(
                rest.getRoute('science_resource_decision', false, 'POST', {
                    scope: this,
                    params: {
                        pk: selection.id
                    },
                    callback: function() {
                        mask.hide();
                        mask = undefined;
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success) {
                            this.getStore().reload();
                        }
                        else
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponível no momento.'
                        });
                    },
                })
            );
        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item!'
            });
        }
    },

